/* Nota Bab 3 T3 (ENGLISH / DLP), ayat ikut buku teks English. Dijana skrip bina_bab3_t3_en.py; jangan sunting dengan tangan. */
window.SUBS=[{"no": "3.1", "name": "Savings & Investments", "col": "#34D399"}, {"no": "3.2", "name": "Credit & Debt Management", "col": "#FB923C"}];
window.SLIDES=[{"sub": "3.1", "n": 1, "N": 17, "kicker": "DEFINITION", "title": "Savings", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Savings</b> refer to excess money deposited in the safe, money box or drawer. Extra money can also be deposited at a bank that will provide returns based on interest rates and savings periods.</p></div><p class=\"sl-p\">There are some common ways of saving in the bank.</p><div class=\"sl-note\"><b>Bulletin:</b> Credit counselling and credit agencies encourage each individual to save 10% of their monthly income.</div>", "fig": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Type of account</th><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Characteristics</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Savings Account</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">The savings account holder can save any amount according to his ability. Interest rates are lower compared to fixed deposit accounts. The account holder can withdraw the savings at any time.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Fixed Deposit Account</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Save a certain amount of money for a certain period of time such as 3 months, 9 months or 1 year tenure. More competitive interest rates. Savings cannot be withdrawn before the maturity date.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Current Account</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Can be used for personal or business purposes. Payment to another party by cheque. Savings will not be paid interest and is subjected to service charges. Overdraft facility.</td></tr></tbody></table></div>", "full": ""}, {"sub": "3.1", "n": 2, "N": 17, "kicker": "DEFINITION", "title": "Investment", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Investment</b> is an alternative step for future returns in the form of current income and capital gains.</p></div><p class=\"sl-p\">Types of investments are shares, unit trust and real estate.</p><div class=\"sl-note\"><b>Bulletin:</b> There are two types of investors, that is aggressive investors (invest in stock market) and moderate investors (buy unit trusts, bonds and equity funds).</div>", "fig": "<div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #38BDF8\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #38BDF8\">SHARES</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Owner of the company</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">A company will issue shares for the purpose of raising capital. The shareholders will receive returns in the form of dividends and capital gains.</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #F472B6\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #F472B6\">UNIT TRUST</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Managed by a professional manager</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">Unit trust companies collect money from investors and the money is invested in various potential companies.</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #FBBF24\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #FBBF24\">REAL ESTATE</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Immovable assets</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">Investments on residential houses, shops, land and others. Factors: economic situations, income-generating capabilities (rent), location and property prospects.</p></div></div>", "full": ""}, {"sub": "3.1", "n": 3, "N": 17, "kicker": "FORMULA", "title": "Simple interest", "body": "<p class=\"sl-p\">Interest for savings are rewards paid by financial institutions such as banks to depositors. The interests can be divided into two types, namely <b>simple interest</b> and <b>compound interest</b>.</p><div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Simple interest</b> is a reward given to the depositor at a certain rate on the deposit amount (principal) for a certain period of time (in years).</p></div><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #34D399;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>I</i> = <i>Prt</i></div><p class=\"sl-p\"><i>I</i> is the interest, <i>P</i> is the principal, <i>r</i> is the rate and <i>t</i> is the time in years.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#34D399\">EXAMPLE 1</b> <div class=\"rv\">Encik Hafiz deposited RM5 000 at Bank Murni with interest rate of 3% per annum. How much is the interest earned by Encik Hafiz after 1 year?</div></div><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">3% of RM5 000 = RM5 000 × <span class=\"fr\"><span>3</span><span>100</span></span> = RM150</div><div class=\"rv\">After 1 year, the interest earned by Encik Hafiz is RM150.</div></div></div><div class=\"sl-note\"><b>Tips:</b> Rate is given in percentage form. Thus, we must divide the rate by a hundred. If the time is given in months, do not forget to change to year by dividing by 12 months.</div></div>", "full": ""}, {"sub": "3.1", "n": 4, "N": 17, "kicker": "EXAMPLE 2", "title": "Calculating simple interest", "body": "<p class=\"sl-p\">Puan Aini deposits RM6 000 in a bank with interest rate of 4% per annum for a period of 3 years. Calculate the total interest that Puan Aini will receive for the 3-year period.</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><div class=\"rv\"><i>P</i> = 6 000, <i>r</i> = 4% = <span class=\"fr\"><span>4</span><span>100</span></span> = 0.04, <i>t</i> = 3</div><div class=\"rv\">Thus, interest <i>I</i> = <i>Prt</i></div><div class=\"rv\">= RM6 000 × <span class=\"fr\"><span>4</span><span>100</span></span> × 3</div><div class=\"rv\">= RM720</div></div></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#34D399\">EXAMPLE 3</b> <div class=\"rv\">Ms Mei deposits RM12 000 in Bank Murni with interest rate of 5% per annum. Calculate the amount of interest Ms Mei will have after 9 months.</div></div><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">9 months = <span class=\"fr\"><span>9</span><span>12</span></span> year</div><div class=\"rv\"><i>I</i> = <i>Prt</i></div><div class=\"rv\">= RM12 000 × <span class=\"fr\"><span>5</span><span>100</span></span> × <span class=\"fr\"><span>9</span><span>12</span></span></div><div class=\"rv\">= RM450</div></div></div>", "full": ""}, {"sub": "3.1", "n": 5, "N": 17, "kicker": "EXAMPLE 4", "title": "Impact of savings period and interest rate", "body": "<p class=\"sl-p\">The changes in savings period in bank give different returns.</p><p class=\"sl-p\"><b>EXAMPLE 4</b> Encik Nazrin deposits RM9 000 in Bank Desa with interest rate of 4% per annum. Calculate the total savings of Encik Nazrin after he has saved for (a) 2 years (b) 3 years</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">(a) 2 years</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">(b) 3 years</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Interest = RM9 000 × <span class=\"fr\"><span>4</span><span>100</span></span> × 2 = RM720</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Interest = RM9 000 × <span class=\"fr\"><span>4</span><span>100</span></span> × 3 = RM1 080</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Total savings = RM9 000 + RM720 = RM9 720</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Total savings = RM9 000 + RM1 080 = RM10 080</td></tr></tbody></table></div><div class=\"sl-note\"><b>Conclusion:</b> The longer the savings period (at the bank), the higher the amount of interest earned. Therefore, the final amount of savings also increases.</div>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><p class=\"sl-p\"><b>EXAMPLE 5</b> Mrs Vanmathy deposits a sum of RM6 000 in a bank. What is the amount of Mrs Vanmathy's savings after 1 year if the interest rate given is (a) 4% per annum (b) 5% per annum</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Interest rate</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Total interest</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Total savings</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">4%</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM6 000 × <span class=\"fr\"><span>4</span><span>100</span></span> × 1 = RM240</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM6 240</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">5%</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM6 000 × <span class=\"fr\"><span>5</span><span>100</span></span> × 1 = RM300</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM6 300</td></tr></tbody></table></div><div class=\"sl-note\"><b>Conclusion:</b> The difference between the total interests received is RM300 − RM240 = RM60. For the same principal, when the interest rates increase, the total savings at the end of the year also increase.</div></div>", "full": ""}, {"sub": "3.1", "n": 6, "N": 17, "kicker": "FORMULA", "title": "Compound interest", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Compound interest</b> is interest that is calculated based on the original principal and also the accumulated interest from the previous period of savings.</p></div><p class=\"sl-p\">For compound interest, the frequency of compounding on the principal can be different. For example, compounded once a year or once every 3 months and so on.</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #34D399;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>MV</i> = <i>P</i>(1 + <span class=\"fr\"><span><i>r</i></span><span><i>n</i></span></span>)<sup><i>nt</i></sup></div><div class=\"sl-note\"><b>Reminder:</b> <i>MV</i> = matured value, <i>P</i> = principal, <i>r</i> = yearly interest rate, <i>n</i> = number of periods the interest is compounded per year, <i>t</i> = term in years</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#34D399\">Referring to Example 4(a)</b> <div class=\"rv\">If compounded once a year, what is his savings at the end of the second year?</div></div><div><b style=\"color:#34D399\">First year</b> <div class=\"rv\">Interest = RM9 000 × <span class=\"fr\"><span>4</span><span>100</span></span> = RM360</div><div class=\"rv\">Savings at the end of the first year = RM9 000 + RM360 = RM9 360</div></div><div><b style=\"color:#34D399\">Second year</b> <div class=\"rv\">Interest is calculated on RM9 360 (principal + first year interest).</div><div class=\"rv\">Interest = RM9 360 × <span class=\"fr\"><span>4</span><span>100</span></span> = RM374.40</div><div class=\"rv\">Savings at the end of the second year = RM9 360 + RM374.40 = RM9 734.40</div></div><div><b style=\"color:#34D399\">Using the formula</b> <div class=\"rv\"><i>P</i> = 9 000, <i>r</i> = 0.04, <i>n</i> = 1, <i>t</i> = 2</div><div class=\"rv\"><i>MV</i> = RM9 000(1 + <span class=\"fr\"><span>0.04</span><span>1</span></span>)<sup>(1)(2)</sup> = RM9 734.40</div></div></div>", "full": ""}, {"sub": "3.1", "n": 7, "N": 17, "kicker": "EXAMPLE 6", "title": "Calculating compound interest", "body": "<p class=\"sl-p\">At the beginning of a year, Mrs Liew saves RM20 000 in savings account with a rate of 6% per annum and compounded every 6 months. What is Mrs Liew's total savings at the end of the second year?</p><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><div class=\"rv\"><i>P</i> = 20 000, <i>r</i> = 0.06, <i>n</i> = 2, <i>t</i> = 2</div><div class=\"rv\"><i>MV</i> = <i>P</i>(1 + <span class=\"fr\"><span><i>r</i></span><span><i>n</i></span></span>)<sup><i>nt</i></sup></div><div class=\"rv\">= RM20 000(1 + <span class=\"fr\"><span>0.06</span><span>2</span></span>)<sup>(2)(2)</sup></div><div class=\"rv\">= RM20 000(1.1255)</div><div class=\"rv\">= RM22 510.18</div></div></div><div class=\"sl-note\"><b>Quiz:</b> What is the impact on the total cumulative returns, if the compounding rate increases in a year?</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#34D399\">EXAMPLE 7</b> <div class=\"rv\">A bank offers 6% interest rate per annum for savings in fixed deposit account. If Iskandar saves RM12 000 at the beginning of the year, how much money is in his fixed deposit account at the end of the year if interest is compounded (a) once every 3 months? (b) once a month?</div></div><div><b style=\"color:#34D399\">(a) <i>n</i> = 4</b> <div class=\"rv\"><i>MV</i> = RM12 000(1 + <span class=\"fr\"><span>0.06</span><span>4</span></span>)<sup>(4)(1)</sup></div><div class=\"rv\">= RM12 736.36</div></div><div><b style=\"color:#34D399\">(b) <i>n</i> = 12</b> <div class=\"rv\"><i>MV</i> = RM12 000(1 + <span class=\"fr\"><span>0.06</span><span>12</span></span>)<sup>(12)(1)</sup></div><div class=\"rv\">= RM12 740.13</div></div><div><div class=\"rv\">From Example 7, it was found that when the compounding frequency increases, the future value of savings also increases.</div></div></div>", "full": ""}, {"sub": "3.1", "n": 8, "N": 17, "kicker": "EXAMPLE 8", "title": "Simple interest compared to compound interest", "body": "<p class=\"sl-p\">Mr Charles deposited RM8 000 in a savings account at Bank Berjaya for 3 years with interest rate of 5% per annum. What is the difference between the amount of interests Mr Charles earned if he was given compound interest (compounded once every 3 months) compared to simple interest?</p><div class=\"sl-note\"><b>Conclusion:</b> Based on Example 8, it is clear that savings with compound interest give higher returns than savings with simple interest.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#34D399\">Simple interest</b> <div class=\"rv\">Interest, <i>I</i> = RM8 000 × <span class=\"fr\"><span>5</span><span>100</span></span> × 3 = RM1 200</div></div><div><b style=\"color:#34D399\">Compound interest</b> <div class=\"rv\"><i>MV</i> = RM8 000(1 + <span class=\"fr\"><span>0.05</span><span>4</span></span>)<sup>(4)(3)</sup> = RM9 286.04</div><div class=\"rv\">Total accumulated interest = RM9 286.04 − RM8 000 = RM1 286.04</div></div><div><div class=\"rv\">Thus, the difference in the amount between simple interest and compound interest = RM1 286.04 − RM1 200 = RM86.04</div></div></div>", "full": ""}, {"sub": "3.1", "n": 9, "N": 17, "kicker": "EXAMPLE 9", "title": "Islamic Banking", "body": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><p class=\"sl-p\">Malaysia practises dual banking systems. They are conventional banking system and Islamic banking system. Islamic banking system is based on Islamic law (syarak), risk is managed according to the agreement, based on the principle of justice, halal and profit-sharing and without usury.</p><div class=\"sl-note\"><b>Bulletin:</b> The principle of wadiah: property or cash received with the agreement of the customer to be deposited in the bank. The bank is responsible for the security of the property or the money.</div></div>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#34D399\">EXAMPLE 9</b> <div class=\"rv\">Encik Osman saved RM25 000 in a savings account in an Islamic bank, according to the principle of wadiah for 1 year. By the end of the year, he received a sum of RM25 750 as a return from the savings. An additional RM750 is a hibah (gift) from the bank. Calculate the percentage of hibah obtained by Encik Osman.</div></div><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">Percentage of hibah = <span class=\"fr\"><span>RM750</span><span>RM25 000</span></span> × 100% = 3%</div></div></div><div class=\"sl-note\"><b>Note:</b> 3% is only a reference for savings and is not fixed.</div></div>", "full": ""}, {"sub": "3.1", "n": 10, "N": 17, "kicker": "FORMULA", "title": "Return on investment (ROI)", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p>Return on investment refers to the return value of each ringgit invested by the investor. In other words, return on investment is also a ratio of profit or loss derived from an investment.</p></div><p class=\"sl-p\">An investment is considered profitable (wise investment) when the present value of the investment and the amount of return received is more than the value of the original investment.</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #34D399;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\">Return on investment = <span class=\"fr\"><span>Total return</span><span>The value of the initial investment</span></span> × 100%</div>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #34D399\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #34D399\">PROFITABLE</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Wise investment</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">The present value of the investment and the amount of return received is more than the value of the original investment.</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #F472B6\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #F472B6\">UNPROFITABLE</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Loss</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">The amount of return and the present value of the return is less than the value of the original investment.</p></div></div><div class=\"sl-note\"><b>Reminder:</b> Unit trust is a good investment alternative for medium term investment (3 to 5 years) and long term (over 5 years).</div></div>", "full": ""}, {"sub": "3.1", "n": 11, "N": 17, "kicker": "EXAMPLE 10", "title": "Return on investment for unit trusts", "body": "<p class=\"sl-p\">On 1 January 2018, Encik Faris invested 4 000 units valued at RM1.50 per unit in a unit trust. For the financial year ending 31 December 2018, the unit trust paid a dividend of 6%. On 1 January 2019, Encik Faris sold all the shares he owned at RM1.80 per unit. What is the return on investment for Encik Faris?</p><div class=\"sl-note\"><b>Bulletin:</b> Return for unit trusts: dividends (usually received at the end of the financial year), bonus shares and capital gain (increase in share price when shares are sold).</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">Initial capital = 4 000 × RM1.50 = RM6 000</div><div class=\"rv\">Dividend = <span class=\"fr\"><span>6</span><span>100</span></span> × RM6 000 = RM360</div><div class=\"rv\">Increase in share price = RM1.80 − RM1.50 = RM0.30</div><div class=\"rv\">Capital gain = RM0.30 × 4 000 units = RM1 200</div><div class=\"rv\">Total return = RM360 + RM1 200 = RM1 560</div><div class=\"rv\">Return on investment = <span class=\"fr\"><span>RM1 560</span><span>RM6 000</span></span> × 100% = 26%</div></div></div>", "full": ""}, {"sub": "3.1", "n": 12, "N": 17, "kicker": "EXAMPLE 11", "title": "Return on investment for real estate", "body": "<p class=\"sl-p\">Encik Kamal bought a shoplot at a price of RM500 000 on 1 January 2017. He paid 10% of the shoplot's purchase price of RM50 000. The shoplot was rented. On 31 December 2026, he sold the shoplot for RM1 100 000. The loan amount still owed to the bank was RM400 000. Meanwhile, the amount that has been amortized to the bank was RM380 000. The total rent collected throughout the possession of the shoplot is RM180 000. Calculate the return on investment obtained by Encik Kamal.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Other charges</th><th style=\"padding:7px 10px;text-align:center;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Amount</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Legal cost</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM12 000</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Stamp duty (during sale and purchase)</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM12 000</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Agent’s commission</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM15 000</td></tr></tbody></table></div><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:16px;line-height:1.5\"><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">Total rent = RM180 000</div><div class=\"rv\">Capital gain = RM1 100 000 − RM400 000 − RM50 000 − RM12 000 − RM12 000 − RM15 000 − RM380 000</div><div class=\"rv\">= RM231 000</div><div class=\"rv\">Total return = RM180 000 + RM231 000 = RM411 000</div><div class=\"rv\">Return on investment = <span class=\"fr\"><span>RM411 000</span><span>RM500 000</span></span> × 100% = 82.2%</div></div></div></div>", "full": ""}, {"sub": "3.1", "n": 13, "N": 17, "kicker": "EXAMPLE 12", "title": "Problem solving: real estate", "body": "<p class=\"sl-p\">Encik Halim bought a house on 1 January 2015 at RM400 000 and cleared 10% down payment of RM40 000. He expects a return of 35% over 20 years. Encik Halim sold the house at a price of RM750 000 after having owned the house for 20 years. The loan amount amortized to the bank was RM600 000. During that period, he managed to earn a rent of RM80 000. What is the return on investment for Encik Halim for 20 years? Did he achieve his desire to get a return of 35%?</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Other expenses</th><th style=\"padding:7px 10px;text-align:center;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Amount</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Stamp duty (during sale and purchase)</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM5 000</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Agent's commission</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM3 000</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Legal cost during sale and purchase</td><td style=\"padding:6px 10px;text-align:center;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM5 000</td></tr></tbody></table></div><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:16px;line-height:1.5\"><div><b style=\"color:#34D399\">Solution:</b> <div class=\"rv\">Return on investment = Rent + Capital gain</div><div class=\"rv\">= RM80 000 + (RM750 000 − RM40 000 − RM600 000 − RM5 000 − RM3 000 − RM5 000)</div><div class=\"rv\">= RM80 000 + RM97 000</div><div class=\"rv\">= RM177 000</div><div class=\"rv\">Return on investment = <span class=\"fr\"><span>RM177 000</span><span>RM400 000</span></span> × 100% = 44.25%</div><div class=\"rv\">Encik Halim managed to obtain a rate of return of 44.25%. This rate exceeds the expected rate of return of 35%.</div></div></div></div>", "full": ""}, {"sub": "3.1", "n": 14, "N": 17, "kicker": "CONCEPT", "title": "Risk, return and liquidity", "body": "<p class=\"sl-p\">Three factors that should be taken into account by an investor prior to making an investment are as follows.</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Factor</th><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Meaning</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Potential investment risks</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">The possibility of an uncertainty that may incur from the investments made.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">The level of returns</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Profit enjoyed by investors from investments.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Liquidity aspects</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Relating to how soon the investment or savings could be cashed out.</td></tr></tbody></table></div>", "fig": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Types of investments</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Risk levels</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Return levels</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Liquidity levels</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Saving</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Risk free</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Low</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Fixed deposits</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Risk free</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Low</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Company shares</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Moderate</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Real estate</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Moderate</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Low</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Unit trust</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Low</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Moderate</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">High</td></tr></tbody></table></div>", "full": ""}, {"sub": "3.1", "n": 15, "N": 17, "kicker": "FORMULA", "title": "Cost averaging strategy", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p>Cost averaging strategy is a technique commonly practised by investors who invest in shares with fixed amount for a certain period such as monthly, quarterly or yearly regardless of the stock market conditions.</p></div><p class=\"sl-p\">Cost averaging strategies can help investors to buy shares with lower average cost and the total number of shares owned will be higher within the same investment period, as opposed to buying them in a lump sum or with a single purchase.</p><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #34D399;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\">Average cost = <span class=\"fr\"><span>Investment amount</span><span>Number of share units owned</span></span></div>", "fig": "<div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #38BDF8\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #38BDF8\">Able to take advantage</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Unit price changes</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">When the stock price is low, more units of shares can be purchased.</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #F472B6\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #F472B6\">Not influenced by emotions</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Consistent</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">Invest consistently on a periodic basis the same amount of money without being influenced by emotions caused by share price fluctuation.</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #FBBF24\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #FBBF24\">Lower the risk of loss</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Regular</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">Total investment is carried out on a regular and consistent manner, which helps investors to avoid losses associated with lump sum investment.</p></div></div>", "full": ""}, {"sub": "3.1", "n": 16, "N": 17, "kicker": "EXAMPLE 13", "title": "Comparing investment strategies", "body": "<p class=\"sl-p\">Below are two investors who plan to invest in shares using different strategies. Puan Rosnah invests a lump sum of RM15 000 to buy Pelita Company shares in January. Puan Mei Lan invests RM3 000 in the designated months to buy the same shares.</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Month</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">January</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">March</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">May</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">August</th><th style=\"padding:7px 10px;text-align:center;font-size:14px;color:#34D399;border:1px solid #22304A;background:#0E1626\">December</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Shares price per unit (RM)</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">1.50</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">1.20</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">1.25</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">1.60</td><td style=\"padding:6px 10px;text-align:center;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">1.50</td></tr></tbody></table></div><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) Calculate the average cost per unit and the number of shares owned by Puan Rosnah and Puan Mei Lan.</span></li><li><span>(b) Who is a wise investor? Justify your answer.</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:18px;line-height:1.5\"><div><b style=\"color:#34D399\">(a) Puan Rosnah</b> <div class=\"rv\">Total shares = <span class=\"fr\"><span>RM15 000</span><span>RM1.50</span></span> = 10 000 share units</div><div class=\"rv\">Average cost per share = RM1.50</div></div><div><b style=\"color:#34D399\">Puan Mei Lan</b> <div class=\"rv\">Share units: 2 000 + 2 500 + 2 400 + 1 875 + 2 000 = 10 775 share units</div><div class=\"rv\">Average cost per share = <span class=\"fr\"><span>RM15 000</span><span>10 775 units</span></span> = RM1.39</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">Puan Mei Lan is a wise investor for practising the cost averaging strategy that helped her to accumulate more shares with the same amount of money, at a lower average cost per share.</div></div></div>", "full": ""}, {"sub": "3.1", "n": 17, "N": 17, "kicker": "EXAMPLE 14", "title": "Problem solving: wise investor", "body": "<p class=\"sl-p\">Encik Rahim, Mr Lim and Mr Kumar had retired from their jobs and each received RM300 000 as gratuity from their company. They use different investment methods to invest. Who is a wise investor?</p><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:left;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Investor</th><th style=\"padding:7px 10px;text-align:left;font-size:13px;color:#34D399;border:1px solid #22304A;background:#0E1626\">Investment method</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Encik Rahim</td><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Bought a medium-cost apartment worth RM120 000 and receives a rental of RM700 per month. The balance is kept in a fixed deposits account with an interest rate of 4% per annum.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Mr Lim</td><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Invested RM300 000 in Manis Company shares at RM1.50 per unit. The company declared a dividend of 7% for that year.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Mr Kumar</td><td style=\"padding:6px 10px;text-align:left;font-size:15px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Deposited RM150 000 into a savings account with an interest rate of 1% per annum. The balance RM150 000 is kept in a fixed deposit account at 3.5% interest rate per annum.</td></tr></tbody></table></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:16px;line-height:1.5\"><div><b style=\"color:#34D399\">Encik Rahim (low level of risk)</b> <div class=\"rv\">Rental = RM700 × 12 = RM8 400, Savings interest = <span class=\"fr\"><span>4</span><span>100</span></span> × RM180 000 = RM7 200</div><div class=\"rv\">ROI = <span class=\"fr\"><span>RM8 400 + RM7 200</span><span>RM300 000</span></span> × 100% = 5.2%</div></div><div><b style=\"color:#34D399\">Mr Lim (high level of risk)</b> <div class=\"rv\">Dividend = RM300 000 × <span class=\"fr\"><span>7</span><span>100</span></span> = RM21 000</div><div class=\"rv\">ROI = <span class=\"fr\"><span>RM21 000</span><span>RM300 000</span></span> × 100% = 7%</div></div><div><b style=\"color:#34D399\">Mr Kumar (low level of risk)</b> <div class=\"rv\">Interest = RM1 500 + RM5 250 = RM6 750</div><div class=\"rv\">ROI = <span class=\"fr\"><span>RM6 750</span><span>RM300 000</span></span> × 100% = 2.25%</div></div><div><div class=\"rv\">Mr Lim is a wise investor because his returns on investment value is higher than Encik Rahim and Mr Kumar. Encik Rahim and Mr Kumar each chose investments with a lower level of risk.</div></div></div>", "full": ""}, {"sub": "3.2", "n": 1, "N": 13, "kicker": "DEFINITION", "title": "Credit and debt", "body": "<div class=\"sl-def\" style=\"--c:#FB923C\"><p>In the financial world, <b>credit</b> means a contractual agreement between the supplier (for instance bank or financial institution) and consumer. The consumer can borrow money from the supplier for any use or purchase and agree to repay within a certain period.</p></div><p class=\"sl-p\">Credit can also mean the amount of money that can be borrowed. For example, for credit card, if the credit card limit is RM10 000, then the card owner has the ability to buy goods or make transactions up to RM10 000 with the card.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div class=\"sl-def\" style=\"--c:#FB923C\"><p><b>Debt</b> usually means an amount that has been borrowed but has not been settled. If a transaction is made using a credit card, the credit will be converted into debt.</p></div><p class=\"sl-p\"><b style=\"color:#FB923C\">How do you manage credit and debt wisely?</b></p><ul class=\"sl-bul\" style=\"--c:#FB923C\"><li><span>Credit card users need to settle the debt payment within the period stipulated by the bank to enjoy interest free period.</span></li><li><span>Pay the outstanding balance listed on the credit card statement.</span></li><li><span>The minimum amount paid by the credit card holder provides opportunity for the bank to charge interest on the balance and may also incur late payment charges.</span></li></ul></div>", "full": ""}, {"sub": "3.2", "n": 2, "N": 13, "kicker": "EXAMPLE 15", "title": "Using a credit facility", "body": "<p class=\"sl-p\">Encik Hakim bought a washing machine at RM2 800 on 10 August 2018. He lacked RM1 000 in cash but has a Bank Cemerlang credit card. He was aware that the shortage of cash could be paid at the end of the month when he received his salary.</p><ul class=\"sl-bul\" style=\"--c:#FB923C\"><li><span>(a) Which credit facility can be used by Encik Hakim to overcome the shortage of money?</span></li><li><span>(b) State the advantages and disadvantages of the payment method you specified in answer (a).</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#FB923C\">Solution:</b> <div class=\"rv\">(a) Encik Hakim can use the credit card facility.</div><div class=\"rv\">(b) The use of credit cards is more convenient if Encik Hakim repays his credit within the interest-free period to avoid any extra charges.</div></div></div>", "full": ""}, {"sub": "3.2", "n": 3, "N": 13, "kicker": "CONCEPT", "title": "Advantages and disadvantages of credit cards", "body": "<p class=\"sl-p\">The use of credit cards is increasingly common today. As a consumer it is important for us to realize and understand the advantages and disadvantages of using credit cards.</p><p class=\"sl-p\">However, not all individuals are eligible for a credit card. There are several conditions that an applicant must adhere to: 21 years old and above, minimum income of RM24 000 per annum and meets other requirements set by the bank.</p>", "fig": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Advantages of credit cards</th><th style=\"padding:7px 10px;text-align:left;font-size:14px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Disadvantages of credit cards</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Credit card users can enjoy a reward system in the form of cash rebates or points redemption.</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Incur charges such as annual fees, finance charges (interest), cash advance interest charges and late payment charges.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Does not require us to carry a lot of cash.</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Overspending.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Easy and efficient payment method.</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Some stores do not accept credit payment.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Convenience of buying goods and services online.</td><td style=\"padding:6px 10px;text-align:left;font-size:16px;font-weight:600;border:1px solid #22304A;vertical-align:top\"></td></tr></tbody></table></div>", "full": ""}, {"sub": "3.2", "n": 4, "N": 13, "kicker": "CONCEPT", "title": "Minimum payment and finance charges", "body": "<p class=\"sl-p\">The credit cardholder will receive a financial statement for the credit card monthly. In the statement, there are details such as credit limit, statement date, latest amount, minimum payment amount, type of charges and so on.</p><p class=\"sl-p\">The cardholder should pay the statement balance immediately so that no financial charges are incurred. But bank provides flexibility by allowing users to pay in a given period, known as the <b>interest free period</b>. Usually this period is 20 days from the statement date.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #38BDF8\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #38BDF8\">MINIMUM PAYMENT</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">5% of the total balance</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">of the credit card statement, or a minimum of RM50</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #F472B6\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #F472B6\">FINANCE CHARGE</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Between 15% and 18% per annum</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">imposed on the balance in daily rate upon expiry of the interest free period</p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #FBBF24\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #FBBF24\">LATE PAYMENT CHARGE</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">Minimum RM10 or 1%</p><p style=\"margin: 4px 0 0; font-size: 18px; color: #94A3B8\">of total outstanding balance, if no payment is made within the interest free period</p></div></div><div class=\"sl-note\"><b>Tips:</b> If you pay only part of it, you will lose the interest-free period.</div></div>", "full": ""}, {"sub": "3.2", "n": 5, "N": 13, "kicker": "EXAMPLE 16", "title": "Credit card usage", "body": "<p class=\"sl-p\">Encik Azman received his credit card statement for January 2019 from Bank Sentosa. The statement shows Encik Azman has the current amount (outstanding balance) of RM4 800. Assuming Encik Azman did not use his credit card in February. The finance charge rate is 18% per annum.</p><ul class=\"sl-bul\" style=\"--c:#FB923C\"><li><span>(a) What is the minimum payment to be paid?</span></li><li><span>(b) If he only makes a minimum payment for January and the statement date is 15 days from the expiry date of the interest free period, what is the balance for the February statement?</span></li><li><span>(c) If he missed his payment for January, what is the balance for his February statement?</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:16px;line-height:1.5\"><div><b style=\"color:#FB923C\">(a)</b> <div class=\"rv\">5% of the current amount = <span class=\"fr\"><span>5</span><span>100</span></span> × RM4 800 = RM240</div><div class=\"rv\">This amount exceeds RM50, thus the minimum payment to be paid by Encik Azman is RM240.</div></div><div><b style=\"color:#FB923C\">(b)</b> <div class=\"rv\">Outstanding balance = RM4 800 − RM240 = RM4 560</div><div class=\"rv\">Period subject to financial charges = 15 days = (15 ÷ 365) years</div><div class=\"rv\">Interest charged = RM4 560 × [(18 ÷ 100) × (15 ÷ 365)] = RM33.73</div><div class=\"rv\">Current amount (Outstanding balance) in February = RM4 560 + RM33.73 = RM4 593.73</div></div><div><b style=\"color:#FB923C\">(c)</b> <div class=\"rv\">Interest charged = RM4 800 × [(18 ÷ 100) × (15 ÷ 365)] = RM35.51</div><div class=\"rv\">Late payment charges = <span class=\"fr\"><span>1</span><span>100</span></span> × (RM4 800 + RM35.51) = RM48.36</div><div class=\"rv\">Current amount in February = RM4 800 + RM35.51 + RM48.36 = RM4 883.87</div></div></div>", "full": ""}, {"sub": "3.2", "n": 6, "N": 13, "kicker": "EXAMPLE 17", "title": "Problem solving: buying online", "body": "<p class=\"sl-p\">Ms Chin wants to buy a handbag online and finds two interesting promotions: (a) Company L in Singapore offers promotional price of SGD240. For orders outside Singapore, SGD40 shipping charges apply. (b) Company V in Malaysia offers promotional price of RM899. Delivery is free for all orders to local address.</p><p class=\"sl-p\">Ms Chin intends to make payment by credit card and she understands that the bank will charge an additional 1% on each transaction from abroad. Assume the current exchange rate is RM1 = SGD0.30. As a wise consumer, which offer should Ms Chin choose? Justify your choice.</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:17px;line-height:1.5\"><div><b style=\"color:#FB923C\">(a) Company L</b> <div class=\"rv\">Promotional price = SGD240 × (1 ÷ 0.30) = RM800.00</div><div class=\"rv\">Postal charges = SGD40 × (1 ÷ 0.30) = RM133.33</div><div class=\"rv\">Additional charges by bank = RM800.00 × <span class=\"fr\"><span>1</span><span>100</span></span> = RM8.00</div><div class=\"rv\">Actual price to be paid = RM800.00 + RM133.33 + RM8.00 = RM941.33</div></div><div><b style=\"color:#FB923C\">(b) Company V</b> <div class=\"rv\">Actual price to be paid = RM899</div></div><div><div class=\"rv\">Although the promotional price offered by Company L is cheaper, but the actual price payable is higher due to the additional charges incurred for online purchases from Company L. So, Ms Chin should buy from Company V to save RM42.33.</div></div></div>", "full": ""}, {"sub": "3.2", "n": 7, "N": 13, "kicker": "FORMULA", "title": "Loan repayment: flat interest", "body": "<p class=\"sl-p\">Each loan will be charged interest on the loan from the date the loan was made. There are two types of calculation methods for loan interest, namely flat interest rate and interest on balance.</p><div class=\"sl-def\" style=\"--c:#FB923C\"><p>In the <b>flat interest</b> method, the interest rate will be calculated on the original loan amount over the term of the loan. So the amount of interest charged per month is fixed.</p></div><div style=\"display:inline-block;margin:6px 0;padding:10px 18px;border:2px solid #FB923C;border-radius:14px;background:#131C2E;font-size:21px;font-weight:700\"><i>A</i> = <i>P</i> + <i>Prt</i> &nbsp;&nbsp; Monthly instalment = <span class=\"fr\"><span><i>A</i></span><span>number of months</span></span></div>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><p class=\"sl-p\"><i>A</i> = total repayment, <i>P</i> = principal, <i>r</i> = interest rate per annum, <i>t</i> = loan period in years.</p><div class=\"sl-def\" style=\"--c:#FB923C\"><p>The <b>monthly instalment</b> is the total amount paid by the borrower to the bank every month to settle the balance of the loan.</p></div><div class=\"sl-note\"><b>Reminder:</b> Total loan balance is the amount deducted from the initial down payment plus the amount of interest charged.</div></div>", "full": ""}, {"sub": "3.2", "n": 8, "N": 13, "kicker": "EXAMPLE 18", "title": "Car loan", "body": "<p class=\"sl-p\">Mrs Yap bought a car worth RM90 000 on credit. She pays 10% down payment and the balance is payable in instalments over 5 years. The flat interest rate imposed by the bank is 3.5% per annum. What is the amount of repayment and monthly instalment payable by Mrs Yap?</p><div class=\"sl-note\"><b>Tips:</b> Total repayment can be calculated with the formula <i>A</i> = <i>P</i> + <i>Prt</i>.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#FB923C\">Solution:</b> <div class=\"rv\">Down payment = 10% × RM90 000 = RM9 000</div><div class=\"rv\">Loan amount = Purchase price − down payment = RM90 000 − RM9 000 = RM81 000</div><div class=\"rv\">Interest for 5 years = RM81 000 × <span class=\"fr\"><span>3.5</span><span>100</span></span> × 5 years = RM14 175</div><div class=\"rv\">Total repayment = RM81 000 + RM14 175 = RM95 175</div><div class=\"rv\">Monthly instalment = <span class=\"fr\"><span>RM95 175</span><span>60 months</span></span> = RM1 586.25 per month</div></div></div>", "full": ""}, {"sub": "3.2", "n": 9, "N": 13, "kicker": "EXAMPLE 19", "title": "Personal loan", "body": "<p class=\"sl-p\">Encik Firdaus obtained a personal loan of RM15 000 from Bank Mulia with an interest rate of 5% per annum. The repayment period is 5 years. What is the monthly instalment to be paid by Encik Firdaus?</p><div class=\"sl-note\"><b>Tips:</b> Total repayment can be calculated with the formula <i>A</i> = <i>P</i> + <i>Prt</i>.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:20px;line-height:1.5\"><div><b style=\"color:#FB923C\">Solution:</b> <div class=\"rv\"><i>A</i> = <i>P</i> + <i>Prt</i></div><div class=\"rv\">Loan, <i>P</i> = RM15 000, <i>r</i> = 5%, <i>t</i> = 5 years</div><div class=\"rv\">Thus, total repayment <i>A</i> = RM15 000 + (RM15 000 × <span class=\"fr\"><span>5</span><span>100</span></span> × 5)</div><div class=\"rv\">= RM15 000 + RM3 750 = RM18 750</div><div class=\"rv\">Monthly instalment = <span class=\"fr\"><span>RM18 750</span><span>60 months</span></span> = RM312.50</div></div></div>", "full": ""}, {"sub": "3.2", "n": 10, "N": 13, "kicker": "EXAMPLE 20", "title": "Interest on balance", "body": "<p class=\"sl-p\">In addition to the flat interest, banks also offer <b>interest on balance</b> for certain types of loans. The amount of interest charged each month on the loan depends on the amount of the loan balance for that month. Since the loan balance is reduced every month, the amount of interest for each month will also be reduced.</p><p class=\"sl-p\"><b>EXAMPLE 20</b> Encik Harith obtained a personal loan of RM12 000 from Bank Mulia with an interest rate of 5% on the balance. The monthly instalment is RM300. Calculate the amount of interest payable by Encik Harith for the first three months.</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:17px;line-height:1.5\"><div><b style=\"color:#FB923C\">First month</b> <div class=\"rv\">First month interest = RM12 000.00 × <span class=\"fr\"><span>5</span><span>100</span></span> × <span class=\"fr\"><span>1</span><span>12</span></span> = RM50.00</div><div class=\"rv\">Balance after first instalment = RM12 050.00 − RM300 = RM11 750.00</div></div><div><b style=\"color:#FB923C\">Second month</b> <div class=\"rv\">Second month interest = RM11 750.00 × <span class=\"fr\"><span>5</span><span>100</span></span> × <span class=\"fr\"><span>1</span><span>12</span></span> = RM48.96</div><div class=\"rv\">Balance after second instalment = RM11 798.96 − RM300 = RM11 498.96</div></div><div><b style=\"color:#FB923C\">Third month</b> <div class=\"rv\">Third month interest = RM11 498.96 × <span class=\"fr\"><span>5</span><span>100</span></span> × <span class=\"fr\"><span>1</span><span>12</span></span> = RM47.91</div><div class=\"rv\">Balance after third instalment = RM11 546.87 − RM300 = RM11 246.87</div></div><div><div class=\"rv\">Total interest for the first three months is RM50.00 + RM48.96 + RM47.91 = RM146.87</div></div></div>", "full": ""}, {"sub": "3.2", "n": 11, "N": 13, "kicker": "EXAMPLE 21", "title": "Vehicle loan", "body": "<p class=\"sl-p\">Sofea wants to buy a car worth RM55 000 and has paid a deposit of RM5 500. The balance will be settled through a vehicle loan. State the advantages and disadvantages of the vehicle loan chosen by Sofea.</p>", "fig": "<div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:left;font-size:16px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Advantages</th><th style=\"padding:7px 10px;text-align:left;font-size:16px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Disadvantages</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:left;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Repayment of vehicle loan in monthly instalments allows Sofea to own the car.</td><td style=\"padding:6px 10px;text-align:left;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">The car will be repossessed if instalments are not made.</td></tr><tr><td style=\"padding:6px 10px;text-align:left;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Does not require a lump sum payment.</td><td style=\"padding:6px 10px;text-align:left;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">The total amount of repayment is high due to interest.</td></tr></tbody></table></div>", "full": ""}, {"sub": "3.2", "n": 12, "N": 13, "kicker": "EXAMPLE 22", "title": "Problem solving: choosing a loan", "body": "<p class=\"sl-p\">Ms Nadia is a teacher with a monthly income of RM3 000. She decides to buy a new car to commute to work. She contacts two banks to get a loan of RM45 000. In addition, every month she also needs RM1 800 to cover other expenses. Suggest to Ms Nadia which bank is best suited for her car loan. State your reasons.</p>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:12px;align-self:flex-start\"><div class=\"sl-table\" style=\"width:100%\"><table style=\"width:100%;border-collapse:collapse;background:#131C2E\"><thead><tr><th style=\"padding:7px 10px;text-align:center;font-size:16px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Loan details</th><th style=\"padding:7px 10px;text-align:center;font-size:16px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Bank A</th><th style=\"padding:7px 10px;text-align:center;font-size:16px;color:#FB923C;border:1px solid #22304A;background:#0E1626\">Bank B</th></tr></thead><tbody><tr><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Loan amount</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM45 000</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">RM45 000</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Payment period</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">9 years</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">5 years</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Interest rate</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">4%</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">4.5%</td></tr><tr><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Guarantor</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Not required</td><td style=\"padding:6px 10px;text-align:center;font-size:18px;font-weight:600;border:1px solid #22304A;vertical-align:top\">Required</td></tr></tbody></table></div><div class=\"sl-note\"><b>Tips:</b> Do not borrow money from unlicensed moneylenders as the loan imposes very high interest charge with daily compound.</div></div>", "full": ""}, {"sub": "3.2", "n": 13, "N": 13, "kicker": "EXAMPLE 22 (continued)", "title": "Solution", "body": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:19px;line-height:1.5\"><div><b style=\"color:#FB923C\">Understanding the problem</b> <div class=\"rv\">The amount of monthly instalments payable by Ms Nadia provided that it is not burdensome.</div></div><div><b style=\"color:#FB923C\">Planning a strategy</b> <div class=\"rv\">Calculate the interest of the loan. Calculate monthly instalment payable.</div></div></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:16px 20px;display:flex;flex-direction:column;gap:8px;font-size:16px;line-height:1.5\"><div><b style=\"color:#FB923C\">Implementing the strategy</b> <div class=\"rv\">Bank A: <i>A</i> = RM45 000 + RM45 000 × <span class=\"fr\"><span>4</span><span>100</span></span> × 9 = RM61 200</div><div class=\"rv\">Monthly instalment = <span class=\"fr\"><span>RM61 200</span><span>108 months</span></span> = RM566.67</div><div class=\"rv\">Bank B: <i>A</i> = RM45 000 + RM45 000 × <span class=\"fr\"><span>4.5</span><span>100</span></span> × 5 = RM55 125</div><div class=\"rv\">Monthly instalment = <span class=\"fr\"><span>RM55 125</span><span>60 months</span></span> = RM918.75</div></div><div><b style=\"color:#FB923C\">Making a conclusion</b> <div class=\"rv\">Balance of Ms Nadia's income = RM3 000 − RM1 800 = RM1 200. Both instalments do not exceed this balance.</div><div class=\"rv\">Ms Nadia should choose Bank A because Bank A charges lower interest compared to Bank B. However, different payment term results in different amount of interest paid. Therefore, Ms Nadia could also choose Bank B.</div></div></div>", "full": ""}];
